import{_ as e,o as r,c as t,a3 as o}from"./chunks/framework.BwzYn71E.js";const k=JSON.parse('{"title":"任务板公约","description":"","frontmatter":{"translationSource":{"title":"任务板公约","archivedAt":"2026-10-31","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=x92HMu2s9XkaihJaPQSJ6v","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/task-board-rules"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/task-board-rules"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/task-board-rules"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/task-board-rules"}]]},"headers":[],"relativePath":"zh/task-board-rules.md","filePath":"zh/page-x92HMu2s9XkaihJaPQSJ6v.md"}'),i={name:"zh/task-board-rules.md"};function s(l,a,d,n,h,p){return r(),t("div",null,[...a[0]||(a[0]=[o('<div class="logistics-content"><span class="logistics-source-anchor" id="任务板公约" aria-hidden="true"></span><h1 id="任务板公约" tabindex="-1">任务板公约 <a class="header-anchor" href="#任务板公约" aria-label="Permalink to &quot;任务板公约&quot;">​</a></h1><blockquote><p>源页面 ID：<code>x92HMu2s9XkaihJaPQSJ6v</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=x92HMu2s9XkaihJaPQSJ6v" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p>任务板的编辑工作在 塔卫二技术开发局 小群 中进行，如果希望参与编辑工作请先向群内人申请入群，各群群主管理等均可，以及一部分外群里常发言的人。并不是所有人都可以进入，或劳苦，或智慧，如果你有证明自己的决心，总能有机会进的。</p><p>如果使用微信登陆或者因为其他腾讯文档的问题而无法获得编辑权限，请在qq群中说明后在腾讯文档申请权限。</p><p>对于拥有编辑权限的人，我们信任您已经从管理员那里了解了日常注意事项。总结起来无外乎这三点：#1) 尊重别人的成果。#2) 输入前要先考虑(照搬还是总结)。#3) 权力越大，责任越大。</p><p>原则上，正在研究的内容应该放置在任务板任务中，研究的小有成果时应该放置于群友成果中，用于公开的内容才放置于知识库。添加名字时应该在前后添加空格，群友名字应该优先采用群昵称及常用称呼，非群友应该添加相关链接指向其账户主页。</p><p>以下是任务板主要编辑者昵称，排名不分先后，可以用于复制。</p><p>jnk、言、Fatal Error A1012、SSnighter、madSUN、kokobird、[Ѵ. Ŋøᵰę]ᶱ、Cipolla_、斯改ms、Zirunwang、恒星泰斗、米斯雀、百亿亿亿亿、Orirock、盐酸利多卡因、xyIvneu_、c、桜夜天華、正交二叉树、Edward Kerman</p></div>',1)])])}const u=e(i,[["render",s]]);export{k as __pageData,u as default};
